def shortage(count, n):
    need = {'r': 2, 'b': 1, 'y': 1}
    total = 0
    for herb in need:
        lack = need[herb] * n - count[herb]
        if lack > 0:
            total += lack
    return total


def solution(bag):
    answer = []
    count = {'r': 0, 'b': 0, 'y': 0, '*': 0}
    for ch in bag:
        count[ch] += 1
    n = 0
    while shortage(count, n + 1) <= count['*']:
        n += 1
    answer = [n, count['*'] - shortage(count, n)]
    return answer

